#include "SceneColor.h"
void SceneColor::Build(ID3D12Device* d,UINT w,UINT h){D3D12_DESCRIPTOR_HEAP_DESC heap={};heap.NumDescriptors=1;heap.Type=D3D12_DESCRIPTOR_HEAP_TYPE_RTV;ThrowIfFailed(d->CreateDescriptorHeap(&heap,IID_PPV_ARGS(&mRtvHeap)));auto desc=CD3DX12_RESOURCE_DESC::Tex2D(Format,w,h,1,1,1,0,D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET);D3D12_CLEAR_VALUE clear={Format,{0,0,0,0}};ThrowIfFailed(d->CreateCommittedResource(&CD3DX12_HEAP_PROPERTIES(D3D12_HEAP_TYPE_DEFAULT),D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE,&clear,IID_PPV_ARGS(&mTex)));d->CreateRenderTargetView(mTex.Get(),nullptr,Rtv());}
void SceneColor::CreateDescriptors(ID3D12Device* d,D3D12_CPU_DESCRIPTOR_HANDLE c,D3D12_GPU_DESCRIPTOR_HANDLE g){mSrv=g;D3D12_SHADER_RESOURCE_VIEW_DESC s={};s.Shader4ComponentMapping=D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;s.Format=Format;s.ViewDimension=D3D12_SRV_DIMENSION_TEXTURE2D;s.Texture2D.MipLevels=1;d->CreateShaderResourceView(mTex.Get(),&s,c);}
void SceneColor::Transition(ID3D12GraphicsCommandList* l,D3D12_RESOURCE_STATES a,D3D12_RESOURCE_STATES b)const{l->ResourceBarrier(1,&CD3DX12_RESOURCE_BARRIER::Transition(mTex.Get(),a,b));}
